// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;

    function setUp() public {
        c = new L1Block();
    }

    function testFuzz_property(
        uint64 number,
        uint64 timestamp,
        uint256 basefee,
        bytes32 hash,
        uint64 sequenceNumber,
        bytes32 batcherHash,
        uint256 l1FeeOverhead,
        uint256 l1FeeScalar
    ) public {
        // depositorAccount is public and uninitialized (zero); that is the only
        // admissible caller for setL1BlockValues.
        address depositor = c.depositorAccount();
        vm.assume(basefee != 0); // keep the domain wide: any nonzero basefee distinguishes

        vm.prank(depositor);
        c.setL1BlockValues(
            number,
            timestamp,
            basefee,
            hash,
            sequenceNumber,
            batcherHash,
            l1FeeOverhead,
            l1FeeScalar
        );

        // General rule: setL1BlockValues is a no-op, so basefee stays zero forever.
        assertTrue(c.basefee() == 0);
    }
}
